\begin{lemma}
\label{lem:reparametrization}
\uses{def:surrounds}
\lean{SmoothSurroundingFamily.reparametrize_average}
\leanok
Let $γ \co E × 𝕊^1 → F$ be a smooth family of loops surrounding
