\begin{theorem}[Smale 1958]
  \lean{sphere_eversion_of_loc}
  \label{sphere_eversion_of_loc}
  \leanok
  There is a homotopy of immersion of $𝕊^2$ into $ℝ^3$ from the inclusion map to
